package com.mfix.pos;

import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.webkit.WebView;

/** Adds live USB printer management, diagnostics and supported receipt reprint to Settings. */
public class PrinterManagementPatchActivity extends InventoryImportPatchActivity {
    private static final String PATCH =
        "(function(){if(window.__mfixPrinterManagementV5)return;window.__mfixPrinterManagementV5=true;"+
        "function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\\\"/g,'&quot;');}"+
        "function printers(){try{return JSON.parse(window.AndroidPrinter.listUsbPrinters()||'[]');}catch(e){return [];}}"+
        "function loadSettings(){try{var s=JSON.parse(localStorage.getItem('mfix_printer_settings_v1')||'{}');return {autoPrint:s.autoPrint!==false&&s.auto!==false,footer:String(s.footer||''),storeName:String(s.storeName||''),storePhone:String(s.storePhone||''),storeAddress:String(s.storeAddress||''),receiptTitle:String(s.receiptTitle||''),paper:String(s.paper||'80'),copies:Math.max(1,Math.min(5,Number(s.copies)||1)),drawer:s.drawer===true};}catch(e){return {autoPrint:true,footer:'',storeName:'',storePhone:'',storeAddress:'',receiptTitle:'',paper:'80',copies:1,drawer:false};}}"+
        "function saveSettings(s){try{localStorage.setItem('mfix_printer_settings_v1',JSON.stringify(s));}catch(e){}}"+
        "function selected(ps){var id=(document.getElementById('mfixUsbPrinterSelect')||{}).value||localStorage.getItem('mfix_default_printer_v1')||'';return ps.find(function(x){return x.id===id||x.name===id;})||ps[0]||null;}"+
        "function showDiagnostics(p){if(!p){toast('לא נמצאה מדפסת USB','err');return;}var d={};try{d=JSON.parse(AndroidPrinter.getUsbPrinterDiagnostics(p.id||p.name)||'{}');}catch(e){d={connected:false,message:String(e)};}var msg=d.connected?'מדפסת: '+String(d.deviceName||p.name)+'\\nVID/PID: '+d.vendorId+':'+d.productId+'\\nהרשאת USB: '+(d.authorized?'כן':'לא')+'\\nסוג: '+String(d.candidateType||'')+'\\nממשקים: '+((d.interfaces||[]).length):'המדפסת אינה זמינה כרגע';alert(msg);}"+
        "function refresh(){var wrap=document.getElementById('printerProfilesWrap');if(!wrap)return false;var old=document.getElementById('mfixPrinterManagement');if(!old){old=document.createElement('div');old.id='mfixPrinterManagement';old.style.marginTop='10px';wrap.appendChild(old);}var ps=printers(),p=selected(ps),s=loadSettings(),saved=localStorage.getItem('mfix_default_printer_v1')||'',status=p?(p.authorized?'מחוברת ומאושרת':'מחוברת — נדרשת הרשאת USB'):'לא נמצאה מדפסת USB',connected=!!p,selectedId=p?p.id:'';old.innerHTML='<div class=\"card\" style=\"background:var(--gray-50);border:1px solid var(--gray-200)\"><b>🖨️ מדפסת והגדרות קבלה</b><div style=\"margin-top:8px\"><label class=\"flabel\">מדפסת ברירת מחדל</label><select id=\"mfixUsbPrinterSelect\" class=\"input\"><option value=\"\">בחר מדפסת USB</option>'+ps.map(function(x){return '<option value=\"'+esc(x.id)+'\" '+((saved&&x.id===saved)||( !saved&&x.id===selectedId)?'selected':'')+'>'+esc(x.name)+' · '+x.vendorId+':'+x.productId+'</option>';}).join('')+'</select></div><div style=\"margin-top:6px;font-size:13px\">'+esc(status)+'</div><div style=\"margin-top:4px;font-size:12px;color:var(--gray-500)\">'+(p?esc(p.name)+' · VID '+p.vendorId+' / PID '+p.productId:'חבר מדפסת USB תרמית נתמכת')+'</div><div style=\"display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px\"><label style=\"font-size:12px;font-weight:700;display:flex;align-items:center;gap:7px\"><input id=\"mfixAutoPrint\" type=\"checkbox\" '+(s.autoPrint?'checked':'')+'> הדפסה אוטומטית לאחר סיום מכירה</label><select id=\"mfixPrinterPaper\" class=\"input\"><option value=\"58\" '+(s.paper==='58'?'selected':'')+'>נייר 58 מ״מ</option><option value=\"80\" '+(s.paper!=='58'?'selected':'')+'>נייר 80 מ״מ</option></select><input id=\"mfixPrinterCopies\" class=\"input\" type=\"number\" min=\"1\" max=\"5\" value=\"'+s.copies+'\" placeholder=\"מספר עותקים\"><label style=\"font-size:12px;font-weight:700;display:flex;align-items:center;gap:7px\"><input id=\"mfixPrinterDrawer\" type=\"checkbox\" '+(s.drawer?'checked':'')+'> פתיחת מגירה לאחר הדפסה</label><input id=\"mfixReceiptTitle\" class=\"input\" maxlength=\"50\" placeholder=\"כותרת קבלה (אופציונלי)\" value=\"'+esc(s.receiptTitle)+'\"><input id=\"mfixStoreName\" class=\"input\" maxlength=\"60\" placeholder=\"שם העסק\" value=\"'+esc(s.storeName)+'\"><input id=\"mfixStorePhone\" class=\"input\" maxlength=\"30\" placeholder=\"טלפון העסק\" value=\"'+esc(s.storePhone)+'\"><input id=\"mfixStoreAddress\" class=\"input\" maxlength=\"100\" placeholder=\"כתובת העסק\" value=\"'+esc(s.storeAddress)+'\"><input id=\"mfixReceiptFooter\" class=\"input\" maxlength=\"80\" placeholder=\"שורת תחתית לקבלה (אופציונלי)\" value=\"'+esc(s.footer)+'\"></div><div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:10px\"><button id=\"mfixPrinterSaveSettings\" class=\"btn btn-ghost\">💾 שמור הגדרות</button><button id=\"mfixPrinterRefresh\" class=\"btn btn-ghost\">🔄 רענן</button><button id=\"mfixPrinterTest\" class=\"btn btn-primary\" '+(connected?'':'disabled')+'>'+ (p&&p.authorized?'🧪 הדפסת ניסיון':'🔐 הרשאה + הדפסת ניסיון') +'</button><button id=\"mfixPrinterReprint\" class=\"btn btn-outline\" '+(connected&&p.authorized?'':'disabled')+'>↩️ הדפס קבלה אחרונה</button><button id=\"mfixPrinterDiag\" class=\"btn btn-ghost\" '+(p?'':'disabled')+'>🔎 אבחון USB</button></div><div style=\"margin-top:8px;font-size:11px;color:var(--gray-500)\">ההדפסה הנתמכת כאן היא USB עם יציאת bulk ו-ESC/POS/Raster. אין כאן טענה לתמיכה ב-Bluetooth/Wi‑Fi.</div></div>';var sel=document.getElementById('mfixUsbPrinterSelect');if(sel)sel.onchange=function(){try{localStorage.setItem('mfix_default_printer_v1',this.value);var q=loadSettings();q.device=this.value;saveSettings(q);}catch(e){}refresh();};document.getElementById('mfixPrinterSaveSettings').onclick=function(){var id=(document.getElementById('mfixUsbPrinterSelect')||{}).value||'';if(id)try{localStorage.setItem('mfix_default_printer_v1',id);}catch(e){}var auto=!!document.getElementById('mfixAutoPrint').checked;saveSettings({device:id,auto:auto,autoPrint:auto,paper:(document.getElementById('mfixPrinterPaper')||{}).value||'80',copies:Math.max(1,Math.min(5,Number(document.getElementById('mfixPrinterCopies').value)||1)),drawer:!!document.getElementById('mfixPrinterDrawer').checked,footer:document.getElementById('mfixReceiptFooter').value.trim(),storeName:document.getElementById('mfixStoreName').value.trim(),storePhone:document.getElementById('mfixStorePhone').value.trim(),storeAddress:document.getElementById('mfixStoreAddress').value.trim(),receiptTitle:document.getElementById('mfixReceiptTitle').value.trim()});toast('הגדרות המדפסת והקבלה נשמרו','ok');};document.getElementById('mfixPrinterRefresh').onclick=refresh;document.getElementById('mfixPrinterTest').onclick=function(){var chosen=selected(printers());if(!chosen){toast('לא נמצאה מדפסת USB','err');return;}if(!window.AndroidPrinter||typeof AndroidPrinter.requestUsbPrinterTest!=='function'){toast('בדיקת USB native אינה זמינה בגרסה זו','err');return;}AndroidPrinter.requestUsbPrinterTest(chosen.id||chosen.name);};document.getElementById('mfixPrinterDiag').onclick=function(){showDiagnostics(selected(printers()));};document.getElementById('mfixPrinterReprint').onclick=function(){var chosen=selected(printers()),sales=[];try{sales=JSON.parse(localStorage.getItem('mfix_completed_sales_v1')||'[]');if(!Array.isArray(sales))sales=[];}catch(e){}var sale=sales.length?sales[sales.length-1]:null;if(!chosen){toast('לא נמצאה מדפסת USB','err');return;}if(!sale){toast('אין קבלה קודמת להדפסה','err');return;}if(typeof window.printDoc==='function'){try{window.printDoc(sale.id);toast('הקבלה האחרונה נשלחה דרך מנגנון ההדפסה המאומת','ok');}catch(e){toast('שגיאה בהדפסה חוזרת','err');}}else{toast('מנגנון הדפסת הקבלה אינו זמין כרגע','err');}};}return true;}"+
        "function install(){refresh();}install();setInterval(install,5000);console.log('[MFIX] printer management patch V5 active');})();";

    /** Installs the same printer-management patch on an already-active Activity chain. */
    public static void install(WebView webView) {
        if (webView == null) return;
        webView.postDelayed(() -> webView.evaluateJavascript(PATCH, null), 3200);
    }

    @Override protected void onCreate(Bundle savedInstanceState){
        super.onCreate(savedInstanceState);
        View root=((ViewGroup)findViewById(android.R.id.content)).getChildAt(0);
        if(root instanceof WebView) install((WebView)root);
    }
}
